import{at as e,it as t,n,vt as r}from"./chunks/framework.D9OOHiq-.js";var i=JSON.parse(`{"title":"EmakiKits","description":"","frontmatter":{},"headers":[],"relativePath":"modules/kits/index.md","filePath":"modules/kits/index.md","lastUpdated":0}`),a={name:`modules/kits/index.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="emakikits" tabindex="-1">EmakiKits <a class="header-anchor" href="#emakikits" aria-label="Permalink to “EmakiKits”">​</a></h1><p>EmakiKits 是配置驱动的礼包模块: 入服, 邀新, 每日, 每周, 每月, CDK, 自选与通用礼包都由 YAML 定义, 不同类型的差异只体现在配置上</p><ul><li>礼包定义放在 <code>plugins/EmakiKits/kits/</code> 下, <strong>一个礼包一个 YAML 文件</strong>, 礼包 id 取自文件内的 <code>id</code> 字段, 与文件名无关</li><li>奖励物品引用 CoreLib 物品来源简写 (<code>minecraft-bread</code>, <code>emakiitem-flame_blade</code> 等), 不再在礼包里手搓材质和 Lore</li><li>奖励共四类: <code>item</code> (物品), <code>money</code> (货币), <code>nested_kit</code> (引用另一个礼包), <code>action</code> (CoreLib 动作管道行)</li><li>自选礼包的每个选项是一个&quot;小礼包&quot; (多条奖励), 通过 <code>max_select: 1</code> 实现只能选一个; 每个礼包在 <code>choice.gui</code> 段内联自己的 GUI 布局</li><li>支持固定奖励, 加权随机奖励, 购买扣费, 累计开启次数档位, 限时窗口 (always / range / cron), 嵌套子礼包与循环引用检测</li><li>领取, 兑换, 购买都走幂等键与审计记录, 重启后可恢复</li></ul><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to “基本信息”">​</a></h2><table tabindex="0"><thead><tr><th>项</th><th>值</th></tr></thead><tbody><tr><td>模块版本</td><td><code>1.0.1</code></td></tr><tr><td>构建产物</td><td><code>EmakiKits-1.0.1.jar</code></td></tr><tr><td>API 坐标</td><td><code>emaki.jiuwu.craft:emaki-kits-api:1.0.1</code> (仅编译期, 不要放进 <code>plugins/</code>)</td></tr><tr><td>主命令</td><td><code>/emakikits</code> (别名 <code>/emakikit</code>, <code>/ekits</code>)</td></tr><tr><td>硬依赖</td><td>EmakiCoreLib (<code>required: true</code>, <code>join-classpath: true</code>)</td></tr><tr><td>权限节点</td><td><code>emakikits.use</code>, <code>emakikits.claim</code>, <code>emakikits.open</code>, <code>emakikits.buy</code>, <code>emakikits.redeem</code>, <code>emakikits.invite</code>, <code>emakikits.admin</code></td></tr><tr><td>支持平台</td><td>Paper 26.1+, 支持 Folia (<code>folia-supported: true</code>)</td></tr></tbody></table><h2 id="页面" tabindex="-1">页面 <a class="header-anchor" href="#页面" aria-label="Permalink to “页面”">​</a></h2><table tabindex="0"><thead><tr><th>页面</th><th>内容</th></tr></thead><tbody><tr><td><a href="./commands.html">命令与权限</a></td><td>玩家命令, 自选, 购买, CDK, 邀新, 管理命令与权限表</td></tr><tr><td><a href="./configuration.html">配置与礼包定义</a></td><td><code>config.yml</code> 键, <code>kits/*.yml</code> 字段, 四类奖励, 内联自选 GUI, 限时窗口</td></tr><tr><td><a href="./api.html">API 与集成</a></td><td><code>emaki-kits-api</code> 的门面, 视图模型与领取事件</td></tr></tbody></table><h2 id="礼包类型" tabindex="-1">礼包类型 <a class="header-anchor" href="#礼包类型" aria-label="Permalink to “礼包类型”">​</a></h2><table tabindex="0"><thead><tr><th>type</th><th>触发方式</th></tr></thead><tbody><tr><td><code>join</code></td><td>新玩家首次进服, 需在游玩时长窗口内输入老玩家邀请码 (UUID 或玩家名)</td></tr><tr><td><code>invite</code></td><td>邀新关系绑定后按 <code>reward_target</code> 发放</td></tr><tr><td><code>daily</code> / <code>weekly</code> / <code>monthly</code></td><td>按 <code>cycle.timezone</code> 的周期边界生成周期键, 每周期一次</td></tr><tr><td><code>cdk</code></td><td><code>/emakikits redeem</code> 兑换, 支持全局一次性与每玩家一次性</td></tr><tr><td><code>choice</code></td><td>打开内联 GUI 选择一个小礼包, <code>max_select</code> 控制可选数量</td></tr><tr><td><code>generic</code></td><td>手动领取, 可叠加购买, 开启次数档位与限时窗口</td></tr></tbody></table><h2 id="配置目录" tabindex="-1">配置目录 <a class="header-anchor" href="#配置目录" aria-label="Permalink to “配置目录”">​</a></h2><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>plugins/EmakiKits/</span></span>
<span class="line"><span>├── config.yml                  # 主配置 (版本, 语言, 存储, 经济, 邀新, CDK, 嵌套, 入服窗口)</span></span>
<span class="line"><span>├── kits/</span></span>
<span class="line"><span>│   ├── join_welcome.yml        # 一文件一礼包, id 取自文件内 id 字段</span></span>
<span class="line"><span>│   ├── invite_reward.yml</span></span>
<span class="line"><span>│   ├── daily_login.yml</span></span>
<span class="line"><span>│   ├── weekly_supply.yml</span></span>
<span class="line"><span>│   ├── monthly_crate.yml</span></span>
<span class="line"><span>│   ├── cdk_global.yml</span></span>
<span class="line"><span>│   ├── cdk_per_player.yml</span></span>
<span class="line"><span>│   ├── choice_starter.yml      # 含内联 choice.gui 布局</span></span>
<span class="line"><span>│   ├── generic_crate.yml</span></span>
<span class="line"><span>│   └── nested_child.yml        # 被其他礼包引用</span></span>
<span class="line"><span>├── gui/                        # 可选外部 GUI 模板 (choice.gui_template 回退用)</span></span>
<span class="line"><span>├── data/                       # 运行期存档 (审计, 幂等键, 计数)</span></span>
<span class="line"><span>└── lang/</span></span>
<span class="line"><span>    ├── zh_CN.yml</span></span>
<span class="line"><span>    └── en_US.yml</span></span></code></pre></div><p><code>release_default_data: true</code> 时首次启动释放内置的 10 个示例礼包; 已有文件不会被覆盖</p><h2 id="依赖与集成" tabindex="-1">依赖与集成 <a class="header-anchor" href="#依赖与集成" aria-label="Permalink to “依赖与集成”">​</a></h2><table tabindex="0"><thead><tr><th>模块</th><th>关系</th></tr></thead><tbody><tr><td>EmakiCoreLib</td><td>硬依赖: 物品来源, <code>createConfiguredItem</code>, 动作管道, GUI 服务, 模板加载, 经济桥, cron 与消息服务</td></tr><tr><td>EmakiItem</td><td>可选: 通过 <code>emakiitem-&lt;物品ID&gt;</code> 简写发放其自定义物品</td></tr><tr><td>Vault / ExcellentEconomy</td><td>可选: <code>money</code> 奖励与 <code>purchase</code> 扣款经 CoreLib 经济桥; 未安装时价格 &gt; 0 的购买一律拒绝</td></tr></tbody></table><h2 id="上手步骤" tabindex="-1">上手步骤 <a class="header-anchor" href="#上手步骤" aria-label="Permalink to “上手步骤”">​</a></h2><ol><li>安装 EmakiCoreLib 与 EmakiKits, 首次启动后确认 <code>plugins/EmakiKits/kits/</code> 下已释放示例礼包</li><li>复制一份 <code>kits/*.yml</code> 改写 <code>id</code>, <code>type</code> 与 <code>rewards</code>, 用 <code>/emakikits reload</code> 热重载</li><li>用 <code>/emakikits list</code> 确认礼包已加载, 用 <code>/emakikits claim &lt;礼包ID&gt;</code> 验证</li><li>自选礼包用 <code>/emakikits choose &lt;礼包ID&gt;</code> 打开内联 GUI; <code>choose</code> 后直接跟选项 id 则跳过 GUI</li></ol>`,16)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};